import json, re, sys, urllib.request
from html.parser import HTMLParser

HUB = "https://western.sare.org/grants/"

class Cards(HTMLParser):
    """Collects <li class="listing ..."> cards: status from class, h3 title, p description, h4.grant-deadline, a.learn href."""
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.cards, self.cur, self.depth, self.tag_stack = [], None, 0, []
        self.capture = None
    def handle_starttag(self, tag, attrs):
        a = dict(attrs); cls = a.get("class", "") or ""
        if tag == "li" and re.search(r"\blisting\b", cls):
            self.cur = {"status": "open" if re.search(r"\bopen\b", cls) else ("closed" if re.search(r"\bclosed\b", cls) else "unknown"),
                        "title": "", "description": "", "deadline_text": "", "url": ""}
            self.depth = 1
            return
        if self.cur is None: return
        if tag == "li": self.depth += 1
        if tag in ("h3", "p") and not self.cur.get({"h3":"title","p":"description"}[tag]):
            self.capture = {"h3":"title","p":"description"}[tag]
        if tag == "h4" and "grant-deadline" in cls: self.capture = "deadline_text"
        if tag == "a" and "learn" in cls.split() and not self.cur["url"]: self.cur["url"] = a.get("href", "")
    def handle_endtag(self, tag):
        if self.cur is None: return
        if tag == "li":
            self.depth -= 1
            if self.depth == 0:
                self.cards.append(self.cur); self.cur = None
        if tag in ("h3", "p", "h4"): self.capture = None
    def handle_data(self, data):
        if self.cur is not None and self.capture:
            self.cur[self.capture] = (self.cur[self.capture] + " " + data).strip()

def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 SALSAV-GrantWatch/1.0"})
    with urllib.request.urlopen(req, timeout=30) as r:
        return r.read().decode("utf-8", "replace")

def parse_deadline(text):
    m = re.search(r"(Closed|Opens|Open|Deadline|Due)[^:]*:\s*([A-Z][a-z]{2,8} \d{1,2}, \d{4})(?: (\d{1,2}:\d{2} [AP]M))?", text or "")
    return {"label": m.group(1), "date": m.group(2), "time": m.group(3)} if m else None

if __name__ == "__main__":
    p = Cards(); p.feed(fetch(sys.argv[1] if len(sys.argv) > 1 else HUB))
    rows = []
    for c in p.cards:
        rows.append({"external_id": c["title"].lower().replace(" ", "-"), "title": c["title"], "url": c["url"],
                     "status": c["status"], "deadline_text": c["deadline_text"], "deadline": parse_deadline(c["deadline_text"]),
                     "description": c["description"][:160]})
    print(json.dumps({"cards": len(rows), "rows": rows}, indent=1))
